import type { MapLayer } from '../components/worldmap/types'
import blockList from '../content/blocks.json'
import { MAX_BLOCK_TYPES } from './scanOptions'

// Every vanilla block ID with its English name, for the block-type autocomplete.
// Generated by `npm run update:blocks` from Mojang's registry and committed, so
// nothing is fetched at runtime. Suggestions only: the input stays free-text,
// so modded blocks and anything newer than this snapshot still scan.

export type BlockType = { id: string; name: string }

export const BLOCKS_VERSION: string = blockList.version

export const BLOCK_TYPES: BlockType[] = blockList.blocks.map(([id, name]) => ({
  id: `minecraft:${id}`,
  name,
}))

const NAMES = new Map(BLOCK_TYPES.map((block) => [block.id, block.name]))

/** The English name for a namespaced ID, or null for modded/unknown blocks. */
export const blockName = (id: string): string | null => NAMES.get(id) ?? null

/** What to call a block in the UI: its English name, else (modded) its ID. */
export const blockLabel = (id: string): string => blockName(id) ?? id

const BY_NAME = new Map(BLOCK_TYPES.map((block) => [block.name.toLowerCase(), block.id]))

/**
 * What someone typed in the block field, as the ID to scan for. An English name
 * ("Nether Portal") maps to its ID; anything else is lower-cased with spaces
 * as underscores (resource locations allow neither capitals nor spaces) and
 * namespaced, so `Nether portal`, `nether_portal` and `minecraft:nether_portal`
 * all land on the same block. Null for blank input.
 */
export function resolveBlockInput(text: string): string | null {
  const trimmed = text.trim()
  if (!trimmed) return null
  const named = BY_NAME.get(trimmed.toLowerCase())
  if (named) return named
  const id = trimmed.toLowerCase().replace(/\s+/g, '_')
  return id.includes(':') ? id : `minecraft:${id}`
}

/**
 * Add `draft` to `blockTypes`, or say why not. The picker's Enter and the page's Scan
 * both go through this, so a typed-but-unadded block follows the same rules.
 */
export function addBlockType(
  blockTypes: string[],
  draft: string,
): { blockTypes: string[]; problem: string | null } {
  const id = resolveBlockInput(draft)
  if (id == null) return { blockTypes, problem: null }
  if (blockTypes.includes(id)) return { blockTypes, problem: `${blockLabel(id)} is already on the list.` }
  if (blockTypes.length >= MAX_BLOCK_TYPES)
    return { blockTypes, problem: `${MAX_BLOCK_TYPES} block types is the most one scan can plot.` }
  return { blockTypes: [...blockTypes, id], problem: null }
}

/** A scan's title from its blocks alone: the block, or the first and a count. */
export function layersTitle(layers: MapLayer[]): string {
  const first = blockLabel(layers[0]?.blockType ?? '')
  return layers.length > 1 ? `${first} + ${layers.length - 1} more` : first
}

